 */
public class WildSleighAssembler : AbstractSleighAssembler<WildAssemblyResolvedPatterns> {
	protected Set<AssemblyPatternBlock> inputContexts;

	protected WildSleighAssembler(
			AbstractAssemblyResolutionFactory<WildAssemblyResolvedPatterns,object> factory,
			AssemblySelector selector, SleighLanguage lang, AssemblyParser parser,
